package dev.eugheist.tc4modern;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.Ingredient;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.registries.*;
/** Original void equipment required by the rare treasure-bag gear pool. */
@EventBusSubscriber(modid=TC4Modern.MODID,bus=EventBusSubscriber.Bus.MOD)
public final class VoidMetal {
 static final DeferredHolder<ArmorMaterial,ArmorMaterial> ARMOR=DeferredHolder.create(Registries.ARMOR_MATERIAL,AlchemyContent.id("void"));
 static final Tier TIER=new net.neoforged.neoforge.common.SimpleTier(net.minecraft.tags.BlockTags.INCORRECT_FOR_DIAMOND_TOOL,150,8,3,10,()->Ingredient.of(PechTrades.mod("primal_charm").getItem()));
 public interface Gear extends thaumcraft.api.IWarpingGear,thaumcraft.api.IRepairable {default int getWarp(ItemStack s,net.minecraft.world.entity.player.Player p){return 1;}}
 @SubscribeEvent static void register(RegisterEvent e){e.register(Registries.ARMOR_MATERIAL,h->{var defense=new java.util.EnumMap<ArmorItem.Type,Integer>(ArmorItem.Type.class);defense.put(ArmorItem.Type.HELMET,3);defense.put(ArmorItem.Type.CHESTPLATE,7);defense.put(ArmorItem.Type.LEGGINGS,6);defense.put(ArmorItem.Type.BOOTS,3);defense.put(ArmorItem.Type.BODY,7);h.register(ARMOR.getId(),new ArmorMaterial(defense,10,net.minecraft.sounds.SoundEvents.ARMOR_EQUIP_IRON,()->Ingredient.of(PechTrades.mod("void_ingot").getItem()),java.util.List.of(new ArmorMaterial.Layer(AlchemyContent.id("void"))),0,0));});e.register(Registries.ITEM,h->{h.register(AlchemyContent.id("void_ingot"),new Item(new Item.Properties()));for(var type:java.util.List.of(ArmorItem.Type.HELMET,ArmorItem.Type.CHESTPLATE,ArmorItem.Type.LEGGINGS,ArmorItem.Type.BOOTS))h.register(AlchemyContent.id("void_"+type.getName()),new Armor(type));h.register(AlchemyContent.id("void_sword"),new Sword());h.register(AlchemyContent.id("void_pickaxe"),new Pick());h.register(AlchemyContent.id("void_axe"),new Axe());h.register(AlchemyContent.id("void_shovel"),new Shovel());h.register(AlchemyContent.id("void_hoe"),new Hoe());});}
 static Item.Properties properties(){return new Item.Properties().rarity(Rarity.UNCOMMON);}
 static void repair(ItemStack s,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity entity){if(!l.isClientSide&&s.isDamaged()&&entity instanceof net.minecraft.world.entity.LivingEntity&&entity.tickCount%20==0)s.setDamageValue(s.getDamageValue()-1);}
 static void weaken(net.minecraft.world.entity.LivingEntity target,net.minecraft.world.entity.LivingEntity hitter,int ticks){if(!target.level().isClientSide&&(!(target instanceof net.minecraft.world.entity.player.Player)||!(hitter instanceof net.minecraft.world.entity.player.Player)||target.level().getServer().isPvpAllowed()))target.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.WEAKNESS,ticks));}
 public static final class Armor extends ArmorItem implements Gear,thaumcraft.api.IRunicArmor {Armor(Type t){super(ARMOR,t,properties().durability(t.getDurability(10)));}public int getRunicCharge(ItemStack s){return 0;}@Override public void inventoryTick(ItemStack s,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity entity,int slot,boolean selected){super.inventoryTick(s,l,entity,slot,selected);repair(s,l,entity);}/* 1.21.1 has no onArmorTick: Inventory.tick() also ticks worn armour through inventoryTick */}
 public static final class Sword extends SwordItem implements Gear {Sword(){super(TIER,properties().attributes(SwordItem.createAttributes(TIER,4,-2.4f)));}@Override public void inventoryTick(ItemStack s,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity e,int slot,boolean selected){super.inventoryTick(s,l,e,slot,selected);repair(s,l,e);}@Override public boolean hurtEnemy(ItemStack s,net.minecraft.world.entity.LivingEntity target,net.minecraft.world.entity.LivingEntity hitter){weaken(target,hitter,60);return super.hurtEnemy(s,target,hitter);}}
 public static final class Pick extends PickaxeItem implements Gear {Pick(){super(TIER,properties().attributes(DiggerItem.createAttributes(TIER,2,-2.8f)));}@Override public void inventoryTick(ItemStack s,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity e,int slot,boolean selected){super.inventoryTick(s,l,e,slot,selected);repair(s,l,e);}@Override public boolean onLeftClickEntity(ItemStack s,net.minecraft.world.entity.player.Player p,net.minecraft.world.entity.Entity e){if(e instanceof net.minecraft.world.entity.LivingEntity target)weaken(target,p,80);return super.onLeftClickEntity(s,p,e);}}
 public static final class Axe extends AxeItem implements Gear {Axe(){super(TIER,properties().attributes(DiggerItem.createAttributes(TIER,3,-3)));}@Override public void inventoryTick(ItemStack s,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity e,int slot,boolean selected){super.inventoryTick(s,l,e,slot,selected);repair(s,l,e);}@Override public boolean onLeftClickEntity(ItemStack s,net.minecraft.world.entity.player.Player p,net.minecraft.world.entity.Entity e){if(e instanceof net.minecraft.world.entity.LivingEntity target)weaken(target,p,80);return super.onLeftClickEntity(s,p,e);}}
 public static final class Shovel extends ShovelItem implements Gear {Shovel(){super(TIER,properties().attributes(DiggerItem.createAttributes(TIER,1,-3)));}@Override public void inventoryTick(ItemStack s,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity e,int slot,boolean selected){super.inventoryTick(s,l,e,slot,selected);repair(s,l,e);}@Override public boolean onLeftClickEntity(ItemStack s,net.minecraft.world.entity.player.Player p,net.minecraft.world.entity.Entity e){if(e instanceof net.minecraft.world.entity.LivingEntity target)weaken(target,p,80);return super.onLeftClickEntity(s,p,e);}}
 public static final class Hoe extends HoeItem implements Gear {Hoe(){super(TIER,properties().attributes(DiggerItem.createAttributes(TIER,-3,0)));}@Override public void inventoryTick(ItemStack s,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity e,int slot,boolean selected){super.inventoryTick(s,l,e,slot,selected);repair(s,l,e);}@Override public boolean onLeftClickEntity(ItemStack s,net.minecraft.world.entity.player.Player p,net.minecraft.world.entity.Entity e){if(e instanceof net.minecraft.world.entity.LivingEntity target)weaken(target,p,80);return super.onLeftClickEntity(s,p,e);}}
}
